const raw = ($input.first().json && ($input.first().json.body || $input.first().json)) || {};

const CATEGORIES = ['餐廳', '小吃', '咖啡', '甜點', '飲料', '烘焙', '伴手禮', '酒吧居酒屋'];
const CITIES = ['台北市', '新北市', '基隆市', '桃園市', '新竹市', '新竹縣', '苗栗縣', '台中市', '彰化縣', '南投縣', '雲林縣', '嘉義市', '嘉義縣', '台南市', '高雄市', '屏東縣', '宜蘭縣', '花蓮縣', '台東縣', '澎湖縣', '金門縣', '連江縣'];
const HANDLE_RE = /^[a-zA-Z0-9._]{1,60}$/;
const PHONE_RE = /^[0-9+\-()#\s]{5,30}$/;

function cleanStr(val, maxLen) {
  if (val === undefined || val === null) return '';
  let s = String(val).trim().slice(0, maxLen);
  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s;
  return s;
}

function fail(error, message) {
  return [{
    json: {
      ok: false,
      status: 400,
      res: JSON.stringify({ ok: false, error, message })
    }
  }];
}

const storeName = cleanStr(raw['店名'], 60);
if (!storeName) return fail('store_name', '請填寫店名');

const category = cleanStr(raw['類別'], 20);
if (!category) {
  return fail('category', '請填寫特色分類（例如：臭豆腐、麵線）');
}

const rawHasStore = raw['有沒有實體店面'];
let hasStorefront = null;
if (rawHasStore === true || rawHasStore === 'true' || rawHasStore === '是') {
  hasStorefront = true;
} else if (rawHasStore === false || rawHasStore === 'false' || rawHasStore === '否') {
  hasStorefront = false;
}
if (hasStorefront === null) {
  return fail('has_storefront', '請選擇有沒有實體店面');
}

const city = String(raw['縣市'] || '').trim().slice(0, 20);
if (!CITIES.includes(city)) return fail('city', '請選擇有效的縣市');

const district = cleanStr(raw['區'], 20);
if (!district) return fail('district', '請填寫區');

const address = cleanStr(raw['地址'], 120);
if (hasStorefront && !address) {
  return fail('address', '有實體店面時請填寫地址');
}

const threads = String(raw['Threads 帳號'] || '').trim().replace(/^@+/, '').slice(0, 60);
const ig = String(raw['IG 帳號'] || '').trim().replace(/^@+/, '').slice(0, 60);
if (!threads && !ig) {
  return fail('social', 'Threads 帳號與 IG 帳號至少要填一個');
}
if (threads && !HANDLE_RE.test(threads)) {
  return fail('threads', 'Threads 帳號格式不正確');
}
if (ig && !HANDLE_RE.test(ig)) {
  return fail('ig', 'IG 帳號格式不正確');
}

const introRaw = raw['一句話介紹'] === undefined || raw['一句話介紹'] === null ? '' : String(raw['一句話介紹']).trim();
if ([...introRaw].length > 30) {
  return fail('intro', '一句話介紹最多 30 個字');
}
const intro = /^[=+\-@\t\r]/.test(introRaw) ? "'" + introRaw : introRaw;

const rawPhone = String(raw['電話'] || '').trim().slice(0, 30);
if (rawPhone && !PHONE_RE.test(rawPhone)) {
  return fail('phone', '電話格式不正確');
}
const phone = cleanStr(rawPhone, 30);
const hours = cleanStr(raw['營業時間'], 100);

const rawConsent = raw['同意聲明'];
const consent = rawConsent === true || rawConsent === 'true' || rawConsent === '是';

const lineAccount = cleanStr(raw['店家 LINE 帳號'], 60);

return [{
  json: {
    ok: true,
    data: {
      '店名': storeName,
      '類別': category,
      '有沒有實體店面': hasStorefront ? '是' : '否',
      hasStorefront,
      '縣市': city,
      '區': district,
      '地址': address,
      'Threads 帳號': threads,
      'IG 帳號': ig,
      '一句話介紹': intro,
      '電話': phone,
      '營業時間': hours,
      '同意聲明': consent ? '是' : '否',
      '店家 LINE 帳號': lineAccount
    }
  }
}];

const data = $('檢查資料').first().json.data;
const rows = $input.all().map((item) => item.json || {});

function norm(str) {
  return String(str || '')
    .replace(/[\uFF01-\uFF5E]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) - 0xFEE0))
    .replace(/[\s\u3000]+/g, '')
    .toLowerCase();
}

const targetName = norm(data['店名']);
const targetCity = norm(data['縣市']);
const targetDistrict = norm(data['區']);

const isDup = rows.some((row) => {
  if (!row['店名']) return false;
  if (String(row['狀態'] || '').trim() === '已下架') return false;
  return (
    norm(row['店名']) === targetName &&
    norm(row['縣市']) === targetCity &&
    norm(row['區']) === targetDistrict
  );
});

if (isDup) {
  return [{
    json: {
      ok: false,
      status: 409,
      res: JSON.stringify({
        ok: false,
        error: 'duplicate',
        message: '這家店已經在地圖上了'
      })
    }
  }];
}

const needGeocode = Boolean(data.hasStorefront && data['地址']);
return [{
  json: {
    ok: true,
    needGeocode,
    data
  }
}];

const data = $('檢查資料').first().json.data;
const needGeocode = Boolean($('查重複').first().json.needGeocode);

let lat = '';
let lng = '';
let geocoded = false;

if (needGeocode) {
  const rawGeo = $input.first().json;
  const hit = Array.isArray(rawGeo) ? rawGeo[0] : rawGeo;
  if (hit && hit.lat !== undefined && hit.lon !== undefined) {
    const latNum = parseFloat(hit.lat);
    const lonNum = parseFloat(hit.lon);
    if (!Number.isNaN(latNum) && !Number.isNaN(lonNum)) {
      lat = String(latNum);
      lng = String(lonNum);
      geocoded = true;
    }
  }
}

const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const timePart = Date.now().toString(36).toUpperCase().slice(-3);
let randPart = '';
for (let i = 0; i < 3; i++) {
  randPart += chars[Math.floor(Math.random() * chars.length)];
}
const id = 'FM-' + timePart + randPart;

const twIso = new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace('Z', '+08:00');

const row = {
  '編號': id,
  '送出時間': twIso,
  '店名': data['店名'],
  '類別': data['類別'],
  '有沒有實體店面': data['有沒有實體店面'],
  '縣市': data['縣市'],
  '區': data['區'],
  '地址': data['地址'],
  'Threads 帳號': data['Threads 帳號'],
  'IG 帳號': data['IG 帳號'],
  '一句話介紹': data['一句話介紹'],
  '電話': data['電話'],
  '營業時間': data['營業時間'],
  '同意聲明': data['同意聲明'],
  '緯度': lat,
  '經度': lng,
  '狀態': '確認中',
  '審核備註': '',
  '審核日期': '',
  '店家 LINE 帳號': data['店家 LINE 帳號'] || ''
};

const links = [];
if (data['Threads 帳號']) links.push('Threads：https://www.threads.net/@' + data['Threads 帳號']);
if (data['IG 帳號']) links.push('IG：https://www.instagram.com/' + data['IG 帳號']);

const lineText = `新店家：${data['店名']}（${data['類別']}，${data['縣市']}${data['區']}）狀態確認中\n編號：${id}\n${links.join('\n')}`;

return [{
  json: {
    row,
    response: {
      ok: true,
      id,
      status: '確認中',
      geocoded,
      message: '已上架，確認中，三天內完成審核'
    },
    lineText
  }
}];
